def _default_jobs(jobs=None):
    if jobs is None:
        env_jobs = os.environ.get("BUILDER_JOBS")
        if env_jobs:
            try:
                jobs = int(env_jobs)
            except ValueError:
                jobs = None
    if jobs is None:
        jobs = os.cpu_count() or 1
    return max(1, int(jobs))


def _is_obj_up_to_date(src, obj):
    if not os.path.exists(obj):
        return False
    return os.path.getmtime(obj) >= os.path.getmtime(src)


def _compile_one_task(task):
    cType, args, src, objName = task
    trace(cType, " ", os.path.basename(src), ">", os.path.basename(objName))
    code, out, err = runProcess(cType, args)
    return src, objName, code, out, err


def _run_compile_tasks(tasks, jobs=None):
    jobs = _default_jobs(jobs)
    if len(tasks) == 0:
        trace("Nothing to compile (all cached)")
        return True

    trace("Compile jobs: ", str(jobs), " | files: ", str(len(tasks)))

    if jobs == 1 or len(tasks) == 1:
        for task in tasks:
            src, objName, code, out, err = _compile_one_task(task)
            if code != 0:
                trace(err.decode("utf-8"))
                trace("Compile failed: ", src)
                return False
            if out:
                trace(out.decode("utf-8"))
        return True

    futures = []
    with ThreadPoolExecutor(max_workers=jobs) as pool:
        for task in tasks:
            futures.append(pool.submit(_compile_one_task, task))

        for fut in as_completed(futures):
            src, objName, code, out, err = fut.result()
            if code != 0:
                trace(err.decode("utf-8"))
                trace("Compile failed: ", src)
                return False
            if out:
                trace(out.decode("utf-8"))

    return True


