def LinuxBuild(folderRoot ,appName, ListOBJS ,useCPP,LDARGS , buildType=0):
        args=[]
                
        cType = "gcc"
        if useCPP:
                cType="g++"
                
        if buildType==0:
            trace("Build Linux aplication")
            args.append("-o")
            export =folderRoot+os.path.sep+appName
            args.append(export)
            objs=""
            for obj in ListOBJS:
                objs+=obj+' '
                args.append(obj)
            #args.append('-s')

            for arg in LDARGS:
                value =arg.strip()
                if len(value)>1:
                    args.append(value)
            rootFolder=os.getcwd()+os.path.sep+"libs"+os.path.sep+"linux"
            args.append("-L"+rootFolder)
            trace("Add folder lib:",rootFolder)
        
                
            trace("Build to "+cType+" "+appName)
            code, out, err=runProcess(cType,args)
            if code!=0:
                trace(err.decode("utf-8") )
                trace("Operation Fail  .. ")
                return False
            
            
        
             
        if buildType==1:
            args.append("-shared")
            args.append("-fPIC")
            args.append("-o")
            export =folderRoot+os.path.sep+appName+".so"
            args.append(export)
            
            objs=""
            for obj in ListOBJS:
                objs+=obj+' '
                args.append(obj)
            #args.append('-s')

            for arg in LDARGS:
                value =arg.strip()
                if len(value)>1:
                    args.append(value)
            
            rootFolder=os.getcwd()+os.path.sep+"libs"+os.path.sep+"linux"
            args.append("-L"+rootFolder)
            trace("Add folder lib:",rootFolder)
            trace("Build to "+cType+" "+appName)

            code, out, err=runProcess(cType,args)
            if code!=0:
                trace(err.decode("utf-8") )
                trace("Operation Fail  .. ")
                return False
            
            
        if buildType==2:
            trace("compile to static lib")
            export =folderRoot+os.path.sep+appName+".a"
            code, out, err=runProcess("rm",["-f",export])
            if code!=0:
                trace(err.decode("utf-8") )
                trace("Operation Fail  .. ")
                return False
            trace(out.decode("utf-8") )

            args.append("-r")
            args.append("-s")
            args.append(export)
            for obj in ListOBJS:
                args.append(obj)

            code, out, err=runProcess("ar",args)
            if code!=0:
                trace(err.decode("utf-8") )
                trace("Operation Fail  .. ")
                return False
            print(out.decode("utf-8") )
            
        trace("Done :) ")
        return True
                             

def LinuxCompile(folderRoot ,name, srcs ,CARGS,CPPARGS, LDARGS,buildType=0,fullBuild=False,runApp=False,jobs=None):
    useCPP=False
    
    
    outFolder=folderRoot+os.path.sep+"obj"+os.path.sep+"Linux"+os.path.sep+name
    createFolderTree(outFolder)
    objsList=[]
    compileTasks=[]

    for src in srcs:
        if not os.path.isfile(src):
            trace("File not exists")
            continue
    
        srcFolder = os.path.dirname(os.path.abspath(src))
        objFolder =outFolder +  srcFolder.replace(folderRoot,"")
        
        createFolderTree(objFolder)
        filename, file_extension = os.path.splitext(src)
        basename = os.path.basename(src)
        basename_without_ext = os.path.splitext(os.path.basename(src))[0]
        objName = objFolder+os.path.sep+basename_without_ext+".o"
        objsList.append(objName)

        cType = "gcc"
        isCPP = len(file_extension)>=3
        if isCPP:
            cType="g++"
            useCPP=True

        if not fullBuild and _is_obj_up_to_date(src, objName):
            trace("Skip file ", src)
            continue

        args=[]
        args.append("-c")
        args.append(src)
        args.append("-o")
        args.append(objName)
        

        if isCPP:
            for arg in CPPARGS: 
                value =arg.strip()
                if len(value)>=2:
                    args.append(arg)
                    print(arg)
        else:
            for arg in CARGS: 
                value =arg.strip()
                if len(value)>=2:
                    args.append(arg)
                    
        if buildType==1:
            args.append("-fPIC")

        compileTasks.append((cType, args, src, objName))

    if not _run_compile_tasks(compileTasks, jobs):
        return False

    trace("Compiling completed")
    
    sucess = LinuxBuild(folderRoot ,name,objsList ,useCPP,LDARGS,buildType)
    
    if runApp and sucess:
        export =folderRoot+os.path.sep+name
        if os.path.isfile(export):
            trace("Running  "+export)
            code, out, err=runProcess(export,[],False)
            if code!=0:
                trace(err.decode("utf-8") )
                return False
            trace(out.decode("utf-8"))
    return sucess

