def WindowsBuild(folderRoot, appName, ListOBJS, useCPP, LDARGS, buildType=0, toolPrefix="x86_64-w64-mingw32-"):
        args=[]

        cType = toolPrefix + "gcc"
        if useCPP:
                cType = toolPrefix + "g++"
        arTool = toolPrefix + "ar"

        if buildType==0:
            trace("Build Windows application")
            export = folderRoot+os.path.sep+appName+".exe"
            exportDir = os.path.dirname(export)
            if exportDir:
                createFolderTree(exportDir)

            args.append("-o")
            args.append(export)
            for obj in ListOBJS:
                args.append(obj)

            for arg in LDARGS:
                value = arg.strip()
                if len(value)>1:
                    args.append(value)

            trace("Build to "+cType+" "+appName)
            code, out, err=runProcess(cType,args)
            if code!=0:
                trace(err.decode("utf-8"))
                trace("Operation Fail  .. ")
                return False

        if buildType==1:
            trace("Build Windows shared library")
            export = folderRoot+os.path.sep+appName+".dll"
            exportDir = os.path.dirname(export)
            if exportDir:
                createFolderTree(exportDir)

            args.append("-shared")
            args.append("-o")
            args.append(export)
            for obj in ListOBJS:
                args.append(obj)

            for arg in LDARGS:
                value = arg.strip()
                if len(value)>1:
                    args.append(value)

            trace("Build to "+cType+" "+appName)
            code, out, err=runProcess(cType,args)
            if code!=0:
                trace(err.decode("utf-8"))
                trace("Operation Fail  .. ")
                return False

        if buildType==2:
            trace("compile to static lib")
            export = folderRoot+os.path.sep+appName+".a"
            exportDir = os.path.dirname(export)
            if exportDir:
                createFolderTree(exportDir)

            code, out, err=runProcess("rm",["-f",export])
            if code!=0:
                trace(err.decode("utf-8"))
                trace("Operation Fail  .. ")
                return False

            args.append("rcs")
            args.append(export)
            for obj in ListOBJS:
                args.append(obj)

            code, out, err=runProcess(arTool,args)
            if code!=0:
                trace(err.decode("utf-8"))
                trace("Operation Fail  .. ")
                return False

        trace("Done :) ")
        return True


def WindowsCompile(folderRoot, name, srcs, CARGS, CPPARGS, LDARGS, buildType=0, fullBuild=False, runApp=False, jobs=None, toolPrefix="x86_64-w64-mingw32-"):
    useCPP=False

    outFolder=folderRoot+os.path.sep+"obj"+os.path.sep+"Windows"+os.path.sep+name
    createFolderTree(outFolder)
    objsList=[]
    compileTasks=[]

    for src in srcs:
        if not os.path.isfile(src):
            trace("File not exists")
            continue

        srcFolder = os.path.dirname(os.path.abspath(src))
        objFolder = outFolder + srcFolder.replace(folderRoot,"")

        createFolderTree(objFolder)
        filename, file_extension = os.path.splitext(src)
        basename_without_ext = os.path.splitext(os.path.basename(src))[0]
        objName = objFolder+os.path.sep+basename_without_ext+".o"
        objsList.append(objName)

        cType = toolPrefix + "gcc"
        isCPP = len(file_extension)>=3
        if isCPP:
            cType = toolPrefix + "g++"
            useCPP=True

        if not fullBuild and _is_obj_up_to_date(src, objName):
            trace("Skip file ", src)
            continue

        args=[]
        args.append("-c")
        args.append(src)
        args.append("-o")
        args.append(objName)

        if isCPP:
            for arg in CPPARGS:
                value = arg.strip()
                if len(value)>=2:
                    args.append(arg)
        else:
            for arg in CARGS:
                value = arg.strip()
                if len(value)>=2:
                    args.append(arg)

        if buildType==1:
            args.append("-D_DLL")

        compileTasks.append((cType, args, src, objName))

    if not _run_compile_tasks(compileTasks, jobs):
        return False

    trace("Compiling completed")
    sucess = WindowsBuild(folderRoot, name, objsList, useCPP, LDARGS, buildType, toolPrefix)

    if runApp and sucess and buildType==0:
        export = folderRoot+os.path.sep+name+".exe"
        if os.path.isfile(export):
            trace("Running "+export)
            code, out, err=runProcess(export,[],False)
            if code!=0:
                trace(err.decode("utf-8"))
                return False
            trace(out.decode("utf-8"))

    return sucess


def _find_first_existing_dir(baseRoot, candidates):
    for rel in candidates:
        path = os.path.join(baseRoot, rel)
        if os.path.isdir(path):
            return path
    return None


def _collect_files_recursive(rootDir, exts):
    files = []
    if not rootDir or not os.path.isdir(rootDir):
        return files
    for root, dirs, names in os.walk(rootDir):
        for name in names:
            lower = name.lower()
            for ext in exts:
                if lower.endswith(ext):
                    files.append(os.path.join(root, name))
                    break
    return files


def discover_project_sources(folderRoot):
    srcs = []
    libbuSrc = _find_first_existing_dir(folderRoot, ["libbu/src", "libbu/libbu/src"])
    libbuInc = _find_first_existing_dir(folderRoot, ["libbu/include", "libbu/libbu/include"])
    graphicsSrc = os.path.join(folderRoot, "graphics", "src")
    mainSrc = os.path.join(folderRoot, "main", "src")
    minizDir = os.path.join(folderRoot, "vendor", "miniz")
    box2dDir = os.path.join(folderRoot, "vendor", "box2d", "src")

    srcs.extend(_collect_files_recursive(libbuSrc, [".c", ".cpp", ".cc", ".cxx"]))
    srcs.extend(_collect_files_recursive(graphicsSrc, [".cpp", ".cc", ".cxx", ".c"]))
    srcs.extend(_collect_files_recursive(mainSrc, [".cpp", ".cc", ".cxx", ".c"]))
    srcs.extend(_collect_files_recursive(minizDir, [".c"]))
    srcs.extend(_collect_files_recursive(box2dDir, [".cpp", ".cc", ".cxx", ".c"]))

    seen = set()
    uniq = []
    for src in srcs:
        norm = os.path.normpath(src)
        if norm in seen:
            continue
        seen.add(norm)
        uniq.append(norm)

    includeDirs = [folderRoot]
    if libbuInc:
        includeDirs.append(libbuInc)
    if libbuSrc:
        includeDirs.append(libbuSrc)
    if os.path.isdir(graphicsSrc):
        includeDirs.append(graphicsSrc)
    if os.path.isdir(mainSrc):
        includeDirs.append(mainSrc)
    if os.path.isdir(minizDir):
        includeDirs.append(minizDir)
    box2dInc = os.path.join(folderRoot, "vendor", "box2d", "include")
    if os.path.isdir(box2dInc):
        includeDirs.append(box2dInc)
    if os.path.isdir(box2dDir):
        includeDirs.append(box2dDir)

    return uniq, includeDirs


def _pkg_config_flags(flag, package):
    if shutil.which("pkg-config") is None:
        return []
    code, out, err = runProcess("pkg-config", [flag, package])
    if code != 0:
        return []
    text = out.decode("utf-8").strip()
    if len(text) == 0:
        return []
    return text.split()


def make_compile_flags(platformName, includeDirs, releaseBuild):
    cargs = ["-std=c11"]
    cppargs = ["-std=c++17"]

    if releaseBuild:
        cargs.extend(["-O3", "-DNDEBUG"])
        cppargs.extend(["-O3", "-DNDEBUG"])
    else:
        cargs.extend(["-O0", "-g", "-DDEBUG", "-D_DEBUG"])
        cppargs.extend(["-O0", "-g", "-DDEBUG", "-D_DEBUG"])

    cargs.extend(["-fdata-sections", "-ffunction-sections"])
    cppargs.extend(["-fdata-sections", "-ffunction-sections"])

    if platformName == "web":
        cargs.append("-DPLATFORM_WEB")
        cppargs.append("-DPLATFORM_WEB")
    elif platformName == "android":
        cargs.append("-DPLATFORM_ANDROID")
        cppargs.append("-DPLATFORM_ANDROID")
    else:
        cargs.append("-DPLATFORM_DESKTOP")
        cppargs.append("-DPLATFORM_DESKTOP")

    for inc in includeDirs:
        cargs.append("-I"+inc)
        cppargs.append("-I"+inc)

    return cargs, cppargs


def make_linux_ldflags(folderRoot):
    ldargs = []
    pkg = _pkg_config_flags("--libs", "raylib")
    if len(pkg) > 0:
        ldargs.extend(pkg)
    else:
        ldargs.append("-L"+os.path.join(folderRoot, "libs", "linux"))
        ldargs.append("-lraylib")
        ldargs.append("-lm")
        ldargs.append("-ldl")
        ldargs.append("-lpthread")
        ldargs.append("-lrt")
        ldargs.append("-lX11")
    if "-lm" not in ldargs:
        ldargs.append("-lm")
    return ldargs


def make_windows_ldflags(folderRoot):
    return [
        "-L"+os.path.join(folderRoot, "libs", "windows"),
        "-lraylib",
        "-lopengl32",
        "-lgdi32",
        "-lwinmm",
        "-lws2_32"
    ]


def make_web_ldflags(folderRoot):
    ldargs = [
        "-s", "USE_GLFW=3",
        "-s", "ASYNCIFY",
        "-s", "ALLOW_MEMORY_GROWTH=1",
        "-s", "FORCE_FILESYSTEM=1"
    ]
    assetsFolder = os.path.join(folderRoot, "bin", "assets")
    if os.path.isdir(assetsFolder):
        ldargs.append("--preload-file")
        ldargs.append(assetsFolder+"@/assets")
    ldargs.append("-L"+os.path.join(folderRoot, "libs", "web"))
    ldargs.append("-lraylib")
    return ldargs


def make_android_ldflags():
    return [
        "-uANativeActivity_onCreate",
        "-lm",
        "-lc",
        "-lraylib",
        "-llog",
        "-landroid",
        "-lEGL",
        "-lGLESv2",
        "-lOpenSLES",
        "-ldl"
    ]


def ensure_output_dir_for_name(folderRoot, name):
    exportDir = os.path.dirname(os.path.join(folderRoot, name))
    if exportDir:
        createFolderTree(exportDir)


def _android_abis_from_csv(text):
    raw = text.split(",")
    abis = []
    for value in raw:
        v = value.strip()
        if len(v) == 0:
            continue
        abis.append(v)
    return abis


def _check_tool_exists(toolName):
    if shutil.which(toolName) is None:
        raise RuntimeError("Missing tool in PATH: "+toolName)


def run_cross_build(args):
    folderRoot = os.path.abspath(args.root)
    srcs, includeDirs = discover_project_sources(folderRoot)
    if len(srcs) == 0:
        raise RuntimeError("No source files found for this project.")

    if args.list_sources:
        trace("Sources found: ", str(len(srcs)))
        for src in srcs:
            trace(" - ", src.replace(folderRoot+os.path.sep, ""))
        return 0

    buildTypeMap = {"app": 0, "shared": 1, "static": 2}
    if args.kind not in buildTypeMap:
        raise RuntimeError("Invalid kind: "+args.kind)

    if args.platform == "web" and args.kind == "shared":
        raise RuntimeError("web does not support kind=shared (use app or static).")

    buildType = buildTypeMap[args.kind]
    cargs, cppargs = make_compile_flags(args.platform, includeDirs, args.release)

    if args.show_config:
        trace("Platform: ", args.platform)
        trace("Kind: ", args.kind)
        trace("Release: ", str(args.release))
        trace("Jobs: ", str(args.jobs))
        trace("Sources: ", str(len(srcs)))
        trace("Root: ", folderRoot)
        return 0

    if args.platform == "linux":
        _check_tool_exists("gcc")
        _check_tool_exists("g++")
        ldargs = make_linux_ldflags(folderRoot)
        exportName = os.path.join("bin", "linux", args.name)
        ensure_output_dir_for_name(folderRoot, exportName)
        ok = LinuxCompile(folderRoot, exportName, srcs, cargs, cppargs, ldargs, buildType, args.full, args.run, args.jobs)
        if not ok:
            return 1
        return 0

    if args.platform == "windows":
        gccTool = args.windows_prefix + "gcc"
        gppTool = args.windows_prefix + "g++"
        arTool = args.windows_prefix + "ar"
        _check_tool_exists(gccTool)
        _check_tool_exists(gppTool)
        _check_tool_exists(arTool)
        ldargs = make_windows_ldflags(folderRoot)
        exportName = os.path.join("bin", "windows", args.name)
        ensure_output_dir_for_name(folderRoot, exportName)
        ok = WindowsCompile(folderRoot, exportName, srcs, cargs, cppargs, ldargs, buildType, args.full, False, args.jobs, args.windows_prefix)
        if not ok:
            return 1
        return 0

    if args.platform == "web":
        _check_tool_exists("emcc")
        _check_tool_exists("em++")
        _check_tool_exists("emar")
        ldargs = make_web_ldflags(folderRoot)
        webName = args.name
        if args.kind == "static":
            webName = os.path.join("bin", "web", args.name)
            ensure_output_dir_for_name(folderRoot, webName)
        ok = WebCompile(folderRoot, webName, srcs, cargs, cppargs, ldargs, buildType, args.full, False, args.jobs)
        if not ok:
            return 1
        return 0

    if args.platform == "android":
        abis = _android_abis_from_csv(args.android_abis)
        if len(abis) == 0:
            raise RuntimeError("No Android ABI selected.")

        if args.kind == "app":
            buildType = 1
        ldargs = make_android_ldflags()
        appName = args.name

        for abi in abis:
            if abi == "armeabi-v7a":
                ok = AndroidARM7Compile(folderRoot, appName, srcs, cargs, cppargs, ldargs, buildType, args.full, False, args.jobs)
            elif abi == "arm64-v8a":
                ok = AndroidARM764Compile(folderRoot, appName, srcs, cargs, cppargs, ldargs, buildType, args.full, False, args.jobs)
            else:
                raise RuntimeError("Unsupported Android ABI: "+abi)
            if not ok:
                return 1

        if args.kind == "app":
            ok = androidCompileJavaNative(
                folderRoot,
                appName,
                args.android_package,
                args.android_label,
                args.android_activity,
                args.run
            )
            if not ok:
                return 1

        return 0

    raise RuntimeError("Unknown platform: "+args.platform)


def parse_cross_args():
    parser = argparse.ArgumentParser(
        description="Cross builder for BuGame (linux/windows/web/android) with incremental cache."
    )
    parser.add_argument("--platform", choices=["linux", "windows", "web", "android"], required=True, help="Build target platform.")
    parser.add_argument("--kind", choices=["app", "shared", "static"], default="app", help="Output kind.")
    parser.add_argument("--name", default="main", help="Target name.")
    parser.add_argument("--root", default=os.getcwd(), help="Project root folder.")
    parser.add_argument("--jobs", type=int, default=max(1, os.cpu_count() or 1), help="Compile jobs.")
    parser.add_argument("--full", action="store_true", help="Force full rebuild (disable cache skip).")
    parser.add_argument("--release", action="store_true", help="Build release flags (default debug flags).")
    parser.add_argument("--run", action="store_true", help="Run output where applicable (linux app / android app install+run).")
    parser.add_argument("--list-sources", action="store_true", help="Only list discovered source files.")
    parser.add_argument("--show-config", action="store_true", help="Print effective config and exit.")

    parser.add_argument("--windows-prefix", default="x86_64-w64-mingw32-", help="Windows cross compiler prefix.")

    parser.add_argument("--android-abis", default="arm64-v8a,armeabi-v7a", help="Comma separated Android ABIs.")
    parser.add_argument("--android-package", default="com.djokersoft.bugame", help="Android package name for app mode.")
    parser.add_argument("--android-label", default="BuGame", help="Android app label for app mode.")
    parser.add_argument("--android-activity", default="NativeLoader", help="Android activity class for app mode.")

    return parser.parse_args()


def main():
    args = parse_cross_args()
    return run_cross_build(args)


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except RuntimeError as exc:
        trace("Error: ", str(exc))
        raise SystemExit(1)

